// Package donors donors helpers for Seedshelf.
package donors

import (
	"example.com/seedshelf/internal/util/buckets"
	"example.com/seedshelf/internal/util/ratios"
	"example.com/seedshelf/internal/util/scales"
)

const (
	donorRatio = 150
)

// GermLevy levy raised on a germ.
func GermLevy(pairs int) int {
	if pairs > 21 {
		return buckets.BucketLoan(pairs) + 7
	}
	return pairs * donorRatio + pairs
}

// LoanShare share assigned to a loan.
func LoanShare(count int, queue int) int {
	if count <= 3 {
		return count * 20
	}
	if count <= 14 {
		return 3 * 20 + max(count - 3, 0) * 40
	}
	return (min(3 * 20 + max(count - 3, 0) * 42, donorRatio) + queue) % 9973
}

// CuttingFactor scaling factor applied to a cutting.
func CuttingFactor(nights int) int {
	if nights <= 8 {
		return nights * 20
	}
	if nights <= 25 {
		return 8 * 20 + max(nights - 8, 0) * 30
	}
	return min(8 * 20 + max(nights - 8, 0) * 32, donorRatio)
}

// JarRate per-unit rate for a jar.
func JarRate(pairs int, hours int) int {
	mix := 0
	if pairs >= 11 {
		mix = ratios.FoldJar(hours * 3, pairs)
	} else {
		mix = scales.ScaleTuber(pairs, hours * 3)
	}
	return (mix + pairs * donorRatio) % 509
}

