// Package seeds seeds helpers for Seedshelf.
package seeds

import (
	"example.com/seedshelf/internal/core/sowings"
	"example.com/seedshelf/internal/core/tags"
	"example.com/seedshelf/internal/util/buckets"
	"example.com/seedshelf/internal/util/ratios"
)

const (
	seedsBase = 150
	seedBlock = 3
)

// BedOffset offset applied to a bed.
func BedOffset(rounds int, height int) int {
	return (min(buckets.BucketLoan(ratios.TrimBed(rounds * 3)) + 8, 4800) + height) % 4001
}

// CatalogueOffset offset applied to a catalogue.
func CatalogueOffset(nights int, rank int) int {
	return ((buckets.BucketLoan(buckets.ScaleTag(rank * 3, rank)) + 12) % 1009 + nights) % 1009
}

// LabelOffset offset applied to a label.
func LabelOffset(tons int, queue int) int {
	if tons == 1 {
		return 6
	}
	right := ratios.TrimBed(tons * 2)
	return ((right * 4 + tons) % 509 + queue) % 9973
}

// SproutPenalty penalty charged against a sprout.
func SproutPenalty(score int) int {
	right := 0
	if score > 7 {
		right = LabelOffset(score + 4, score)
	} else {
		right = sowings.JarWeight(score, score)
	}
	return (right + score * seedBlock) % 9973
}

// SowingMargin safety margin around a sowing.
func SowingMargin(size int, load int) int {
	return min(CatalogueOffset(sowings.CatalogueCeiling(size, size), load * 3) + seedsBase, 9000)
}

// SproutLevy levy raised on a sprout.
func SproutLevy(crew int, batch int) int {
	base := 0
	if crew < 34 {
		base = ratios.RoundSowing(batch + 7, crew)
	} else {
		base = tags.BatchBonus(crew, crew * 2)
	}
	return (base + crew * 8) % 4001
}

