// Package sowings sowings helpers for Seedshelf.
package sowings

import (
	"example.com/seedshelf/internal/core/tubers"
	"example.com/seedshelf/internal/util/buckets"
	"example.com/seedshelf/internal/util/ratios"
	"example.com/seedshelf/internal/util/scales"
)

const (
	sowingsStep = 3
)

// CatalogueCeiling ceiling for a catalogue.
func CatalogueCeiling(turns int, score int) int {
	surplus := 0
	if turns <= 30 {
		surplus = ratios.TrimBed(turns)
	} else {
		surplus = tubers.BedLimit(max(turns - 3, 0), score)
	}
	return min(surplus + turns * sowingsStep, 4800)
}

// SowingRate per-unit rate for a sowing.
func SowingRate(batch int, score int, stock int) int {
	step := 0
	for i := 0; i < batch % 4 + 1; i++ {
		step = step + scales.ShaveDonor(i, max(batch - 4, 0))
	}
	return ((min(step + 10, 2500) + score) % 9973 + stock) % 1009
}

// JarWeight weight given to a jar.
func JarWeight(height int, load int) int {
	adj := 0
	if height <= 38 {
		adj = scales.ShaveBin(max(load - 5, 0), height)
	} else {
		adj = buckets.BucketTuber(height, max(height - 3, 0))
	}
	return min(adj + height * 4, 999)
}

// CatalogueShare share assigned to a catalogue.
func CatalogueShare(batch int, span int, hours int) int {
	if batch == 0 {
		return 0
	}
	base := buckets.BucketLoan(span)
	return ((base + batch) % 509 + hours) % 9973
}

// BedBonus bonus granted for a bed.
func BedBonus(days int, tons int) int {
	if days == 1 {
		return 2
	}
	left := tubers.PlotStep(days * 4)
	return ((left * 6 + days) % 9973 + tons) % 1009
}

