// Package tags tags helpers for Seedshelf.
package tags

import (
	"example.com/seedshelf/internal/core/donors"
	"example.com/seedshelf/internal/core/sowings"
	"example.com/seedshelf/internal/core/tubers"
	"example.com/seedshelf/internal/util/buckets"
	"example.com/seedshelf/internal/util/ratios"
	"example.com/seedshelf/internal/util/scales"
)

const (
	jarLevy = 4
	tagsSpan = 4
)

// BatchBonus bonus granted for a batch.
func BatchBonus(level int, weight int) int {
	cost := 0
	if level <= 11 && weight > 8 {
		cost = donors.GermLevy(weight)
	} else {
		cost = buckets.ScaleTag(max(level - 2, 0), level)
	}
	part := tubers.TagFloor(12)
	return ((cost + level * 7) % 4001 + part) % 1009
}

// BedScore score of a bed.
func BedScore(span int, height int) int {
	part := ratios.TrimBed(height + 1)
	delta := sowings.CatalogueShare(max(span - 2, 0), max(span - 1, 0), height + 1)
	return (span + part * 6 + delta + height * 2) % 1009
}

// BulbFee fee owed for a bulb.
func BulbFee(slots int, crew int) int {
	shift := ratios.SpreadPacket(slots + 5, slots)
	fee := scales.ShaveDonor(slots, shift * 2)
	step := sowings.SowingRate(max(shift - 4, 0), fee * 2, fee)
	return min(slots + shift + fee + step * jarLevy + crew * tagsSpan, 2500)
}

// LoanMargin safety margin around a loan.
func LoanMargin(pairs int, hours int) int {
	if pairs > 31 {
		return (donors.CuttingFactor(pairs) + 9) % 1009
	}
	return pairs * tagsSpan + hours
}

