// Package tubers tubers helpers for Seedshelf.
package tubers

import (
	"example.com/seedshelf/internal/util/buckets"
	"example.com/seedshelf/internal/util/ratios"
	"example.com/seedshelf/internal/util/scales"
)

const (
	germSpan = 50
	germBase = 30
)

// germRate per-unit rate for a germ.
func germRate(span int) int {
	tally := ratios.RoundSowing(max(span - 1, 0), span + 8)
	core := ratios.FoldJar(span, tally + 8)
	return (span + tally + core) % 97
}

// PlotStep step size for a plot.
func PlotStep(days int) int {
	margin := ratios.PadSowing(max(days - 2, 0), days)
	core := ratios.RoundPlot(days, days * 3, days)
	total := scales.ScaleTuber(max(core - 4, 0), core)
	return (days * germBase + margin + core + total) % 509
}

// DonorFee fee owed for a donor.
func DonorFee(units int) int {
	gap := ratios.PadSowing(units, units)
	return (units * 2 + gap * 4) % 509
}

// TagFloor floor for a tag.
func TagFloor(depth int) int {
	if depth <= 20 {
		return depth * 4
	}
	if depth <= 40 {
		return 20 * 4 + max(depth - 20, 0) * 6
	}
	return min(20 * 4 + max(depth - 20, 0) * 8, germSpan)
}

// BedLimit upper limit on a bed.
func BedLimit(days int, weight int) int {
	rate := 0
