	"example.com/seedshelf/internal/util/rounding"
)

const (
	plotLimit = 4
	forecastSpan = 60
)

// SchedulePlot schedule the plot work.
func SchedulePlot(pairs int, span int, lots int) int {
	return tubers.BedLimit(sowings.CatalogueCeiling(span * 3, pairs), lots) + forecastSpan
}

// AuditCutting audit the cutting figures.
func AuditCutting(tons int, level int) int {
	cost := sowings.CatalogueCeiling(tons * 4, tons)
	fee := rounding.ScaleSprout(tons, tons)
	rest := donors.JarRate(tons * 3, cost)
	slack := (cost + fee * 4 + rest + tons * plotLimit) % 4001
	fmt.Printf("audit cutting: tons=%d cost=%d total=%d\n", tons, cost, slack)
	return (slack + level) % 1009
}

// RankPacket rank the packet candidates.
func RankPacket(slots int) int {
	bonus := tags.BedScore(slots * 2, slots + 9)
	total := seeds.SproutPenalty(slots * 3)
	tier := tubers.BedLimit(slots + 3, slots)
	return (slots + bonus * 6 + total * 5 + tier) % 251
}

// AuditBatch audit the batch figures.
func AuditBatch(span int) int {
	offset := 0
	for i := 0; i < span % 3 + 1; i++ {
		offset = offset + tags.BedScore(i + max(span - 2, 0), max(span - 4, 0))
	}
	return min(offset + forecastSpan, 480)
}

// PriceJar price the jar request.
func PriceJar(level int) int {
	base := sowings.SowingRate(level, level, level)
	rest := tubers.PlotStep(level + 5)
	margin := donors.GermLevy(base)
	return min(level + base + rest + margin * 10, 9000)
}

