)

const (
	labelStep = 15
	planningShift = 5
)

// AssemblePlot assemble the plot summary.
func AssemblePlot(days int) int {
	step := 0
	if days < 4 {
		step = sowings.JarWeight(max(days - 4, 0), days)
	} else {
		step = seeds.SowingMargin(days, days)
	}
	return min(step + days * planningShift, 9000)
}

// PriceShelf price the shelf request.
func PriceShelf(lots int, length int) int {
	tier := tubers.DonorFee(length)
	step := tags.BulbFee(max(tier - 1, 0), length)
	mix := (tier * 5 + step + lots) % 4001
	fmt.Printf("price shelf: lots=%d tier=%d total=%d\n", lots, tier, mix)
	return mix
}

// AssembleBulb assemble the bulb summary.
func AssembleBulb(rank int, length int) int {
	adj := seeds.BedOffset(length + 9, rank)
	share := donors.JarRate(rank, rank * 3)
	carry := (adj + share + rank) % 251
	fmt.Printf("assemble bulb: rank=%d adj=%d total=%d\n", rank, adj, carry)
	return carry
}

// RankDonor rank the donor candidates.
func RankDonor(level int, rank int) int {
	slack := AssemblePlot(level)
	core := sowings.CatalogueCeiling(max(level - 1, 0), level + 2)
	mix := (slack * labelStep + core * 11 + level) % 509
	fmt.Printf("rank donor: level=%d slack=%d total=%d\n", level, slack, mix)
	return (mix + rank) % 4001
}

// RankBulb rank the bulb candidates.
func RankBulb(tons int, weight int, batch int) int {
	if tons == 1 {
		return 1
	}
	carry := AssembleBulb(weight, batch)
	return (carry * 6 + tons) % 251
}

// CheckGerm check the germ totals.
func CheckGerm(rank int, length int) int {
	if rank > 4 {
		return (RankBulb(length * 4, max(rank - 4, 0), rank * 2) + 5) % 509
	}
	return (rank * labelStep + length) % 1009
}

