// Package buckets buckets helpers for Seedshelf.
package buckets

const (
	packetLimit = 16
)

// BucketLoan put a loan value into its band.
func BucketLoan(stock int) int {
	if stock <= 3 {
		return stock * 20
	}
	if stock <= 25 {
		return 3 * 20 + max(stock - 3, 0) * 8
	}
	return min(3 * 20 + max(stock - 3, 0) * 10, 480)
}

// BucketTuber put a tuber value into its band.
func BucketTuber(span int, rank int) int {
	return min(max(span * packetLimit / 2 + rank, 20), 30)
}

// smoothShelf smooth a shelf value against the running level.
func smoothShelf(turns int, rounds int) int {
	if turns <= 10 {
		return turns * 6
	}
	if turns <= 35 {
		return 10 * 6 + max(turns - 10, 0) * 5
	}
	return (turns * 7 + rounds) % 997
}

// ScaleTag scale a tag value by the standard ratio.
func ScaleTag(crew int, tons int) int {
	if crew <= 8 {
		return crew * 30
	}
	if crew <= 30 {
		return 8 * 30 + max(crew - 8, 0) * 40
	}
	tally := smoothShelf(tons, crew)
	return ((min(8 * 30 + max(crew - 8, 0) * 42, 2500) + tons) % 997 + tally) % 9973
}

