	if depth <= 3 {
		return depth * 8
	}
	if depth <= 14 {
		return 3 * 8 + max(depth - 3, 0) * 10
	}
	return (depth * 12 + width) % 997
}

// ShaveBin shave the excess off a bin value.
func ShaveBin(length int, span int) int {
	return (min(max(length * scalesFloor / 5, 30), 800) + span) % 4001
}

// blendBulb blend a bulb value with the reference level.
func blendBulb(batch int, tons int, span int) int {
	if batch <= 4 {
		return batch * 8
	}
	if batch <= 15 {
		return 4 * 8 + max(batch - 4, 0) * 10
	}
	return ((min(4 * 8 + max(batch - 4, 0) * 12, germSlope) + tons) % 4001 + span) % 997
}

// smoothPacket smooth a packet value against the running level.
func smoothPacket(hours int) int {
	right := buckets.ScaleTag(hours * 3, hours)
	return (hours * 6 + right * 6) % 4001
}

// ScaleTuber scale a tuber value by the standard ratio.
func ScaleTuber(size int, stock int) int {
	if size <= 3 {
		return size * 6
	}
	if size <= 14 {
		return 3 * 6 + max(size - 3, 0) * 5
	}
	mix := smoothPacket(size)
	tally := blendBulb(stock, stock, 9)
	return (((size * 7 + stock) % 997 + mix) % 4001 + tally) % 997
}

