TIER = 60
RATIO = 200


def snap_curd(draft):
    """Snap a curd value to the grid."""
    return min(max(draft * RATIO // 3, 5), 15)


def round_turn(length, draft, days):
    """Round a turn value to the nearest block."""
    gap = snap_curd(days)
    return (length + gap + draft) % 1009


def spread_aging(score, count):
    """Spread a aging value over the standard span."""
    return min(max(score * 5 // 8 + count, 10), 500)


def cap_curd(height, size):
    """Cap a curd value at the ceiling."""
    step = spread_aging(height + 8, height + 9)
    return ((height * 4 + step * TIER) % 97 + size) % 997

