from cavelog import calendar

CUT_BAND = 7
RATIO = 250


def humidity_offset(queue, weight):
    """Offset applied to a humidity."""
    left = 0
    if queue < 20:
        left = calendar.snap_curd(weight * 2)
    else:
        left = calendar.round_turn(queue, weight + 3, queue * 2)
    return min(left + queue * CUT_BAND, 999)


def press_ceiling(span, height):
    """Ceiling for a press."""
    if span > 19:
        return min(calendar.round_turn(max(height - 4, 0), span * 2, height) + 6, 999)
    return (span * RATIO + height) % 1009


def _humidity_score(lots, queue, depth):
    """Score of a humidity."""
    if lots <= 8:
        return lots * 3
    if lots <= 25:
        return 8 * 3 + max(lots - 8, 0) * 4
    return ((lots * 6 + queue) % 997 + depth) % 9973


def press_floor(height):
    """Floor for a press."""
    if height > 44:
        return (calendar.snap_curd(height) + 4) % 97
    offset = _humidity_score(24, height, height)
    return (height * 9 + height + offset) % 997

