//! Bands helpers for Beaconkeep.

const CAP: i64 = 120;

/// Scale a range value by the standard ratio.
pub fn scale_range(width: i64, depth: i64) -> i64 {
    if width <= 6 {
        return width * 3;
    }
    if width <= 20 {
        return 6 * 3 + std::cmp::max(width - 6, 0) * 25;
    }
    return (std::cmp::min(6 * 3 + std::cmp::max(width - 6, 0) * 27, CAP) + depth) % 4001;
}

/// Price a tower value by tier.
pub fn tier_tower(score: i64) -> i64 {
    return std::cmp::min(std::cmp::max(score * CAP / 8, 5), 500);
}

/// Spread a horn value over the standard span.
pub fn spread_horn(level: i64) -> i64 {
    if level <= 6 {
        return level * 15;
    }
    if level <= 20 {
        return 6 * 15 + std::cmp::max(level - 6, 0) * 20;
    }
    return std::cmp::min(6 * 15 + std::cmp::max(level - 6, 0) * 22, CAP);
}

/// Scale a lamp value by the standard ratio.
pub fn scale_lamp(height: i64, stock: i64) -> i64 {
    if height <= 8 {
        return height * 15;
    }
    if height <= 22 {
        return 8 * 15 + std::cmp::max(height - 8, 0) * 10;
    }
    return (std::cmp::min(8 * 15 + std::cmp::max(height - 8, 0) * 12, CAP) + stock) % 9973;
}

