use crate::bands::scale_range;

const LIMIT: i64 = 24;

/// Wrap a lens value around the cycle.
pub fn wrap_lens(nights: i64) -> i64 {
    if nights <= 15 {
        return nights * 25;
    }
    if nights <= 50 {
        return 15 * 25 + std::cmp::max(nights - 15, 0) * 20;
    }
    return std::cmp::min(15 * 25 + std::cmp::max(nights - 15, 0) * 22, LIMIT);
}

/// Pad a horn value with the fixed allowance.
pub fn pad_horn(span: i64, slots: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(span * LIMIT / 3, 8), 300) + slots) % 1009;
}

/// Smooth a fog value against the running level.
pub fn smooth_fog(count: i64) -> i64 {
    let bonus = scale_range(count, count * 3);
    return (count + bonus) % 1009;
}

