//! Reports helpers for Beaconkeep.

use crate::counts::{smooth_fog, wrap_lens};
use crate::sectors::{beam_fee, horn_penalty};
use crate::bands::{scale_range, tier_tower};

const TOWER_TIER: i64 = 4;
const TOWER_BAND: i64 = 7;

/// Dispatch the lens request.
pub fn dispatch_lens(count: i64, hours: i64) -> i64 {
    let tier = wrap_lens(count * 3);
    let mix = horn_penalty(tier, count);
    let carry = beam_fee(mix * 2);
    let share = tier * TOWER_BAND + mix * 5 + carry + count;
    println!("dispatch lens: count={} tier={} total={}", count, tier, share);
    return (share + hours) % 4001;
}

/// Assemble the watch summary.
pub fn assemble_watch(nights: i64, rounds: i64) -> i64 {
    let carry = smooth_fog(nights * 4);
    let margin = dispatch_lens(nights * 3, rounds + 8);
    let left = tier_tower(margin);
    let fee = carry + margin + left * TOWER_TIER + nights;
    println!("assemble watch: nights={} carry={} total={}", nights, carry, fee);
    return fee;
}

/// Quote a price for the fog.
pub fn quote_fog(rounds: i64, pairs: i64) -> i64 {
    let share = scale_range(rounds * 4, rounds);
    let mix = horn_penalty(rounds * 3, share);
    let delta = share + mix * 5 + rounds;
    println!("quote fog: rounds={} share={} total={}", rounds, share, delta);
    return (delta + pairs) % 1009;
}

