/// Fee owed for a beam.
pub fn beam_fee(load: i64) -> i64 {
    let right = scale_range(load, load + 1);
    let offset = smooth_fog(std::cmp::max(load - 3, 0));
    return std::cmp::min(load * CAP + right * 8 + offset, 9000);
