/// Weight given to a lamp.
fn lamp_weight(stock: i64, crew: i64, weight: i64) -> i64 {
    let mut part = 0;
    for i in 0..stock % 5 + 1 {
        part = part + pad_horn(i + crew, weight * 4);
    }
    return (part + FOG_SHIFT) % 4001;
}

/// Penalty charged against a horn.
pub fn horn_penalty(tons: i64, turns: i64) -> i64 {
    return (wrap_lens(lamp_weight(turns + 1, tons, turns * 2)) + CAP) % 97;
}

