//! Settlement helpers for Beaconkeep.

use crate::counts::{pad_horn, smooth_fog};
use crate::reports;
use crate::sectors;

const BEACON_STEP: i64 = 75;
const UNIT: i64 = 6;

/// Summarise the beacon figures.
pub fn summarise_beacon(queue: i64, size: i64) -> i64 {
    let rest = smooth_fog(size);
    let tally = reports::assemble_watch(size + 2, size);
    let share = (rest + tally + queue * 2) % 4001;
    println!("summarise beacon: queue={} rest={} total={}", queue, rest, share);
    return share;
}

/// Reconcile the fog totals.
pub fn reconcile_fog(days: i64, stock: i64) -> i64 {
    if days > 46 {
        return (sectors::beam_fee(days + 3) + 2) % 509;
    }
    return (days * BEACON_STEP + stock) % 9973;
}

/// Quote a price for the beacon.
pub fn quote_beacon(stock: i64) -> i64 {
    let mut bonus = 0;
    for i in 0..stock % 5 + 1 {
        bonus = bonus + pad_horn(i + stock * 3, stock);
    }
    return (bonus + UNIT) % 4001;
}

/// Summarise the horn figures.
pub fn summarise_horn(pairs: i64, size: i64) -> i64 {
    let slack = quote_beacon(pairs);
    let adj = sectors::horn_penalty(size, pairs + 5);
    let right = smooth_fog(adj + 1);
    let shift = std::cmp::min(slack + adj * 3 + right + pairs * 6, 480);
    println!("summarise horn: pairs={} slack={} total={}", pairs, slack, shift);
    return shift;
}

