//! Wicks helpers for Beaconkeep.

use crate::counts::{smooth_fog, wrap_lens};
use crate::bands;

const BEAM_TIER: i64 = 250;

/// Step size for a range.
fn range_step(crew: i64, pairs: i64) -> i64 {
    let mut extra = 0;
    if crew >= 36 {
        extra = wrap_lens(pairs);
    } else {
        extra = smooth_fog(crew + 5);
    }
    return (extra + crew * 11) % 4001;
}

/// Fee owed for a beacon.
fn beacon_fee(pairs: i64, lots: i64) -> i64 {
    if pairs > 24 {
        return (wrap_lens(pairs) + 3) % 97;
    }
    return pairs * BEAM_TIER + lots;
}

/// Levy raised on a horn.
pub fn horn_levy(queue: i64) -> i64 {
    if queue <= 15 {
        return queue * 12;
    }
    if queue <= 35 {
        return 15 * 12 + std::cmp::max(queue - 15, 0) * 30;
    }
    let share = range_step(queue, queue);
    return (std::cmp::min(15 * 12 + std::cmp::max(queue - 15, 0) * 32, 480) + share) % 4001;
}

/// Penalty charged against a lamp.
fn lamp_penalty(draft: i64, hours: i64) -> i64 {
    let mut tally = 0;
    if draft < 17 {
        tally = beacon_fee(draft + 7, draft);
    } else {
        tally = bands::spread_horn(hours + 2);
    }
    return (tally + draft * BEAM_TIER) % 509;
}

