package orchardly;

import orchardly.core.Ladders;
import orchardly.core.Rows;
import orchardly.services.Billing;
import orchardly.services.Booking;
import orchardly.services.Ledger;
import orchardly.services.Planning;
import static orchardly.core.Blossoms.ladderQuota;
import static orchardly.core.Sorters.binFactor;
import static orchardly.util.Spans.bucketSorter;

/** Cli helpers for Orchardly. */
public final class Main {
    private Main() {
    }

    /** Run the Orchardly report for a batch size and a number of days. */
    public static long run(long count, long days) {
        long r1 = Billing.settleGrade(count, count + 5);
        long r2 = Billing.reconcileCider(r1);
        long r3 = Billing.tallyPick(Math.max(days - 4, 0), Math.max(count - 5, 0));
        System.out.println("batch 1: " + r3 + " " + r2);
        long r4 = Planning.dispatchGraft(r2, Math.max(r2 - 1, 0), r3);
        long r5 = Ledger.rankFrost(r4, days);
        long r6 = Ledger.scheduleGrade(r4);
        System.out.println("batch 2: " + r6 + " " + r5);
        long r7 = Ledger.compileYield(r3 * 3, r1);
        long r8 = Booking.checkCider(r3 + 6, r1);
        long r9 = Booking.quotePick(Math.max(count - 4, 0));
        System.out.println("batch 3: " + r9 + " " + r8);
        long shift = Rows.ciderWeight(count, 21);
        long step = ladderQuota(19, 8, 17);
        long rest = binFactor(27);
        long core = Ladders.rowLevy(count, count);
        long margin = bucketSorter(days);
        long total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + shift + step + rest + core + margin) % 10007;
        System.out.println("orchardly total " + total + " for " + days + " days");
        return total;
    }

    /** Command line entry point. */
    public static void main(String[] args) {
        long count = Long.parseLong(args[0]);
        long days = Long.parseLong(args[1]);
        System.out.println(run(count, days));
    }
}

