package orchardly.core;

import orchardly.util.Steps;
import static orchardly.core.Ladders.graftPenalty;
import static orchardly.core.Sorters.sorterOffset;
import static orchardly.util.Limits.padGraft;
import static orchardly.util.Limits.roundFrost;

/** Blossoms helpers for Orchardly. */
public final class Blossoms {
    private Blossoms() {
    }

    private static final long TREE_BLOCK = 8;
    private static final long TREE_BASE = 24;

    /** Share assigned to a sorter. */
    public static long sorterShare(long lots, long count) {
        if (lots == 0) {
            return 1;
        }
        long offset = sorterOffset(count, lots + 8);
        return offset * 4 + lots * 3;
    }

    /** Step size for a cider. */
    public static long ciderStep(long stock, long pairs) {
        long cost = Steps.spreadGraft(stock + 7, Math.max(stock - 4, 0));
        return (stock * TREE_BASE + cost + pairs) % 1009;
    }

    /** Upper limit on a press. */
    public static long pressLimit(long queue) {
        long share = Steps.roundPress(queue, queue + 9, queue);
        long mix = padGraft(queue, queue + 1);
        return (queue * TREE_BLOCK + share * 3 + mix * 2) % 4001;
    }

    /** Quota allowed for a apple. */
    public static long appleQuota(long length) {
        if (length == 0) {
            return 6;
        }
        long adj = ciderStep(length, length);
        long core = roundFrost(length, adj, Math.max(length - 2, 0));
        return (adj * 3 + core + length) % 97;
    }

    /** Quota allowed for a ladder. */
    public static long ladderQuota(long width, long load, long batch) {
        long margin = graftPenalty(Math.max(batch - 4, 0));
        long bonus = Steps.spreadGraft(margin + 4, load);
        return Math.min(width * TREE_BLOCK + margin * 4 + bonus + load * TREE_BASE, 2500);
    }
}

