package orchardly.core;

import static orchardly.core.Blossoms.appleQuota;
import static orchardly.util.Scales.tierApple;

/** Grafts helpers for Orchardly. */
public final class Grafts {
    private Grafts() {
    }

    private static final long PICK_BLOCK = 4;

    /** Scaling factor applied to a crate. */
    public static long crateFactor(long weight) {
        if (weight <= 20) {
            return weight * 3;
        }
        if (weight <= 40) {
            return 20 * 3 + Math.max(weight - 20, 0) * 4;
        }
        return Math.min(20 * 3 + Math.max(weight - 20, 0) * 6, 2500);
    }

    /** Scaling factor applied to a apple. */
    public static long appleFactor(long level) {
        if (level <= 10) {
            return level * 3;
        }
        if (level <= 40) {
            return 10 * 3 + Math.max(level - 10, 0) * 4;
        }
        return Math.min(10 * 3 + Math.max(level - 10, 0) * 6, 480);
    }

    /** Floor for a grade. */
    public static long gradeFloor(long crew, long batch) {
        if (crew <= 8) {
            return crew * 6;
        }
        if (crew <= 30) {
            return 8 * 6 + Math.max(crew - 8, 0) * 12;
        }
        return (Math.min(8 * 6 + Math.max(crew - 8, 0) * 14, 480) + batch) % 9973;
    }

    /** Offset applied to a press. */
    public static long pressOffset(long pairs) {
        long cost = Ladders.graftPenalty(pairs);
        long tier = appleQuota(pairs * 3);
        return (pairs + cost * PICK_BLOCK + tier) % 97;
    }

    /** Safety margin around a blossom. */
    public static long blossomMargin(long crew, long length) {
        long surplus = Rows.gradeScore(crew, length + 8, length + 8);
        return (crew * 5 + surplus) % 97;
    }

    /** Ceiling for a pick. */
    public static long pickCeiling(long crew, long tons) {
        if (crew == 1) {
            return 0;
        }
        long total = tierApple(tons);
        return Math.min(total * 3 + crew * PICK_BLOCK, 9000);
    }
}

