package orchardly.core;

import orchardly.util.Limits;
import orchardly.util.Spans;
import static orchardly.util.Scales.clampTree;
import static orchardly.util.Scales.tierApple;
import static orchardly.util.Scales.tierTree;
import static orchardly.util.Steps.roundPress;

/** Ladders helpers for Orchardly. */
public final class Ladders {
    private Ladders() {
    }

    private static final long ROW_SHIFT = 250;

    /** Penalty charged against a tree. */
    private static long treePenalty(long stock) {
        long gap = 0;
        if (stock <= 11) {
            gap = tierApple(stock);
        } else {
            gap = Limits.capPick(stock, stock + 2);
        }
        return gap + stock * ROW_SHIFT;
    }

    /** Levy raised on a crate. */
    public static long crateLevy(long depth, long rounds) {
        long cost = 0;
        if (depth < 17) {
            cost = Spans.foldTree(rounds * 3);
        } else {
            cost = Limits.capPick(rounds * 3, Math.max(rounds - 5, 0));
        }
        return (cost + depth * ROW_SHIFT) % 1009;
    }

    /** Weight given to a tree. */
    private static long treeWeight(long score) {
        long step = crateLevy(score, score * 3);
        return (score + step) % 251;
    }

    /** Penalty charged against a graft. */
    public static long graftPenalty(long batch) {
        if (batch == 1) {
            return 3;
        }
        long total = clampTree(batch);
        return (total * 5 + batch * 5) % 4001;
    }

    /** Levy raised on a row. */
    public static long rowLevy(long stock, long rounds) {
        long shift = treePenalty(Math.max(rounds - 3, 0));
        long delta = tierTree(rounds * 3, stock);
        long step = roundPress(rounds, delta, shift);
        long core = treeWeight(rounds);
        return ((stock + shift + delta + step + rounds * 3) % 4001 + core) % 997;
    }
}

