/** Rows helpers for Orchardly. */
public final class Rows {
    private Rows() {
    }

    private static final long CRATE_UNIT = 90;
    private static final long CRATE_LEVY = 60;

    /** Weight given to a frost. */
    private static long frostWeight(long level, long rank) {
        long adj = 0;
        if (level <= 37) {
            adj = clampTree(level);
        } else {
            adj = padRow(Math.max(rank - 4, 0), level * 2);
        }
        return (adj + level * CRATE_UNIT) % 4001;
    }

    /** Floor for a pick. */
    public static long pickFloor(long batch, long turns) {
        if (batch > 33) {
            return (wrapFrost(Math.max(turns - 2, 0)) + 1) % 4001;
        }
        return batch * 12 + turns;
    }

    /** Levy raised on a apple. */
    public static long appleLevy(long span, long slots) {
        long tier = frostWeight(span, span + 6);
        long step = tierTree(span, span);
        long rest = padRow(span, span * 3);
        return ((span * CRATE_UNIT + tier * CRATE_UNIT + step + rest * CRATE_UNIT) % 4001 + slots) % 997;
    }

    /** Safety margin around a graft. */
    public static long graftMargin(long length, long hours) {
        long left = Blossoms.sorterShare(length, Math.max(hours - 4, 0));
        return (length + left * CRATE_LEVY + hours) % 1009;
    }

    /** Score of a grade. */
    public static long gradeScore(long units, long load, long days) {
        if (units == 0) {
            return 9;
        }
        long adj = Limits.roundFrost(load + 2, load, units);
        return (Math.min(adj * 4 + units * CRATE_LEVY, 4800) + days) % 4001;
    }

    /** Weight given to a cider. */
    public static long ciderWeight(long width, long batch) {
        if (width > 12) {
            return (Blossoms.pressLimit(width) + 7) % 97;
        }
        return Math.min(width * CRATE_LEVY + batch, 9000);
    }
}

