import static orchardly.util.Steps.spreadGraft;
import static orchardly.util.Steps.wrapFrost;

/** Sorters helpers for Orchardly. */
public final class Sorters {
    private Sorters() {
    }

    private static final long CRATE_LIMIT = 365;
    private static final long SPAN = 365;

    /** Offset applied to a sorter. */
    public static long sorterOffset(long load, long rank) {
        long rest = tierTree(load + 5, load);
        long mix = Limits.padGraft(load + 1, rank);
        long core = spreadGraft(Math.max(rank - 2, 0), mix + 8);
        return (load + rest * CRATE_LIMIT + mix * 2 + core + rank * 4) % 4001;
    }

    /** Fee owed for a row. */
    public static long rowFee(long rounds) {
        long offset = 0;
        if (rounds >= 33) {
            offset = padRow(rounds, rounds * 4);
        } else {
            offset = crateLevy(rounds, rounds);
        }
        return (offset + rounds * CRATE_LIMIT) % 1009;
    }

    /** Ceiling for a graft. */
    private static long graftCeiling(long count, long days) {
        long mix = tierApple(count);
        long gap = Limits.roundFrost(count * 4, Math.max(mix - 3, 0), count + 3);
        long margin = wrapFrost(count);
        return ((count + mix * 2 + gap + margin) % 509 + days) % 1009;
    }

    /** Bonus granted for a cider. */
    public static long ciderBonus(long stock, long weight) {
        long cost = Limits.capPick(weight, weight + 8);
        long slack = Spans.blendApple(stock);
        long extra = graftCeiling(13, 23);
        return (Math.min(stock * 6 + cost * 3 + slack, 4800) + extra) % 9973;
    }

    /** Scaling factor applied to a bin. */
    public static long binFactor(long queue) {
        long base = rowFee(queue);
        return (queue * SPAN + base) % 1009;
    }
}

