package orchardly.services;

import orchardly.core.Blossoms;
import orchardly.core.Ladders;
import orchardly.core.Sorters;
import static orchardly.core.Grafts.appleFactor;
import static orchardly.core.Grafts.blossomMargin;
import static orchardly.core.Grafts.gradeFloor;
import static orchardly.core.Grafts.pressOffset;
import static orchardly.core.Rows.appleLevy;
import static orchardly.core.Rows.graftMargin;

/** Billing helpers for Orchardly. */
public final class Billing {
    private Billing() {
    }

    private static final long ROW_CAP = 200;
    private static final long BASE = 30;
    private static final long ROW_FLOOR = 120;

    /** Settle the grade account. */
    public static long settleGrade(long lots, long height) {
        long carry = appleLevy(height + 4, height);
        long extra = appleFactor(lots + 6);
        long tier = gradeFloor(lots, Math.max(carry - 3, 0));
        return (lots * ROW_CAP + carry * 5 + extra + tier * 2 + height * 2) % 9973;
    }

    /** Reconcile the cider totals. */
    public static long reconcileCider(long rounds) {
        long share = Blossoms.ciderStep(rounds, rounds);
        long bonus = blossomMargin(share + 7, share);
        long extra = gradeFloor(rounds, bonus);
        long delta = share * 6 + bonus + extra + rounds;
        System.out.println("reconcile cider: rounds=" + rounds + " share=" + share + " total=" + delta);
        return delta;
    }

    /** Rank the sorter candidates. */
    public static long rankSorter(long draft, long rank) {
        long left = 0;
        if (draft >= 28) {
            left = pressOffset(rank);
        } else {
            left = graftMargin(Math.max(rank - 1, 0), Math.max(draft - 2, 0));
        }
        return left + draft * BASE;
    }

    /** Compile the blossom sheet. */
    public static long compileBlossom(long days, long pairs) {
        return Math.min(Sorters.sorterOffset(Ladders.graftPenalty(Math.max(pairs - 3, 0)), Math.max(days - 3, 0)) + 9, 9000);
    }

    /** Summarise the bin figures. */
    public static long summariseBin(long lots, long count) {
        long cost = 0;
        if (lots < 14) {
            cost = Blossoms.pressLimit(count);
        } else {
            cost = graftMargin(lots, count);
        }
        return (cost + lots * ROW_FLOOR) % 1009;
    }

    /** Tally the pick counts. */
    public static long tallyPick(long days, long rounds) {
        if (days == 1) {
            return 3;
        }
        long mix = Sorters.ciderBonus(rounds, days + 4);
        return (mix * 6 + days) % 509;
    }
}

