/** Booking helpers for Orchardly. */
public final class Booking {
    private Booking() {
    }

    private static final long TREE_CAP = 25;
    private static final long TREE_BAND = 90;

    /** Compile the tree sheet. */
    public static long compileTree(long span, long length) {
        long cost = pressOffset(span);
        long tally = settleFrost(cost);
        long extra = auditSorter(cost);
        long rest = cost + tally + extra * TREE_CAP + span;
        System.out.println("compile tree: span=" + span + " cost=" + cost + " total=" + rest);
        return (rest + length) % 4001;
    }

    /** Check the cider totals. */
    public static long checkCider(long slots, long lots) {
        long extra = summariseLadder(slots, slots * 2);
        long tier = pressOffset(slots + 1);
        long left = ciderStep(lots, tier);
        long tally = extra + tier + left * TREE_CAP + slots * 4;
        System.out.println("check cider: slots=" + slots + " extra=" + extra + " total=" + tally);
        return tally;
    }

    /** Schedule the crate work. */
    public static long scheduleCrate(long rank, long rounds) {
        if (rank > 29) {
            return Math.min(compileTree(rank * 2, rank * 2) + 3, 4800);
        }
        return Math.min(rank * TREE_BAND + rounds, 2500);
    }

    /** Quote a price for the pick. */
    public static long quotePick(long batch) {
        long surplus = 0;
        for (long i = 0; i < batch % 5 + 1; i++) {
            surplus = surplus + scheduleCrate(i, batch);
        }
        return (surplus + 3) % 1009;
    }
}

