/** Ledger helpers for Orchardly. */
public final class Ledger {
    private Ledger() {
    }

    private static final long FLOOR = 200;
    private static final long BLOCK = 5;

    /** Rank the frost candidates. */
    public static long rankFrost(long depth, long level) {
        if (depth == 1) {
            return 4;
        }
        long bonus = Planning.compileRow(level * 4, level);
        long left = Billing.compileBlossom(depth, depth);
        return (bonus * FLOOR + left * 4 + depth * 3) % 97;
    }

    /** Compile the sorter sheet. */
    public static long compileSorter(long span, long tons, long nights) {
        if (span == 0) {
            return 0;
        }
        long delta = Sorters.sorterOffset(tons, nights);
        long core = Blossoms.ciderStep(Math.max(tons - 3, 0), tons);
        return (delta + core * 2 + span * FLOOR) % 1009;
    }

    /** Schedule the ladder work. */
    public static long scheduleLadder(long size) {
        if (size > 29) {
            return (compileSorter(size + 3, Math.max(size - 4, 0), size + 1) + 5) % 97;
        }
        return (size * FLOOR + size) % 97;
    }

    /** Schedule the grade work. */
    public static long scheduleGrade(long level) {
        long fee = Grafts.pressOffset(level);
        long part = crateLevy(level, fee);
        long rest = (fee + part + level) % 509;
        System.out.println("schedule grade: level=" + level + " fee=" + fee + " total=" + rest);
        return rest;
    }

    /** Audit the sorter figures. */
    public static long auditSorter(long slots) {
        if (slots == 0) {
            return 1;
        }
        long margin = crateLevy(slots + 5, slots * 3);
        long adj = Billing.summariseBin(margin, margin + 9);
        return (margin * 2 + adj + slots) % 1009;
    }

    /** Compile the yield sheet. */
    public static long compileYield(long slots, long lots) {
        long offset = Billing.rankSorter(lots, slots * 4);
        return (slots * BLOCK + offset * 2 + lots * 6) % 509;
    }
}

