        long surplus = compileRow(nights, nights + 8);
        long offset = pressOffset(surplus + 1);
        return ((surplus * 2 + offset + nights) % 97 + tons) % 1009;
    }

    /** Plan the row step. */
    public static long planRow(long turns) {
        if (turns == 0) {
