package orchardly.util;

/** Limits helpers for Orchardly. */
public final class Limits {
    private Limits() {
    }

    private static final long BIN_LIMIT = 75;

    /** Smooth a tree value against the running level. */
    private static long smoothTree(long weight) {
        if (weight <= 4) {
            return weight * 10;
        }
        if (weight <= 16) {
            return 4 * 10 + Math.max(weight - 4, 0) * 5;
        }
        return Math.min(4 * 10 + Math.max(weight - 4, 0) * 7, BIN_LIMIT);
