        if (tons <= 22) {
            return 6 * 8 + Math.max(tons - 6, 0) * 15;
        }
        return ((Math.min(6 * 8 + Math.max(tons - 6, 0) * 17, BIN_LIMIT) + weight) % 4001 + width) % 4001;
