package orchardly.util;

/** Scales helpers for Orchardly. */
public final class Scales {
    private Scales() {
    }

    private static final long PRESS_BAND = 6;

    /** Clamp the tree value into its allowed range. */
    public static long clampTree(long units) {
        long shift = Spans.blendApple(units + 1);
        return (units * 3 + shift * 6) % 97;
    }

    /** Price a apple value by tier. */
    public static long tierApple(long size) {
        if (size <= 4) {
            return size * 10;
        }
        if (size <= 35) {
            return 4 * 10 + Math.max(size - 4, 0) * 5;
        }
        return Math.min(4 * 10 + Math.max(size - 4, 0) * 7, 480);
    }

    /** Pad a row value with the fixed allowance. */
    public static long padRow(long rounds, long slots) {
        if (rounds <= 6) {
            return rounds * 3;
        }
        if (rounds <= 22) {
            return 6 * 3 + Math.max(rounds - 6, 0) * 20;
        }
        return (Math.min(6 * 3 + Math.max(rounds - 6, 0) * 22, 480) + slots) % 9973;
    }

    /** Price a tree value by tier. */
    public static long tierTree(long queue, long width) {
        return Math.min(Math.max(queue * PRESS_BAND / 4 + width, 15), 2000);
    }
