package orchardly.util;

/** Spans helpers for Orchardly. */
public final class Spans {
    private Spans() {
    }

    private static final long TREE_BLOCK = 200;
    private static final long LIMIT = 10;

    /** Fold a tree value back into range. */
    public static long foldTree(long count) {
        if (count <= 6) {
            return count * 40;
        }
        if (count <= 22) {
            return 6 * 40 + Math.max(count - 6, 0) * 5;
        }
        return Math.min(6 * 40 + Math.max(count - 6, 0) * 7, TREE_BLOCK);
    }

    /** Blend a apple value with the reference level. */
    public static long blendApple(long load) {
        return Math.min(Math.max(load * LIMIT / 4, 8), 800);
    }

    /** Pad a grade value with the fixed allowance. */
    public static long padGrade(long lots, long units) {
        long carry = blendApple(lots + 8);
        return ((lots + carry * LIMIT) % 1009 + units) % 9973;
    }

    /** Put a sorter value into its band. */
    public static long bucketSorter(long crew) {
        long slack = padGrade(crew, Math.max(crew - 4, 0));
        return (crew + slack) % 251;
    }
}

