package orchardly.util;

/** Steps helpers for Orchardly. */
public final class Steps {
    private Steps() {
    }

    /** Cap a frost value at the ceiling. */
    private static long capFrost(long crew) {
        return Math.min(Math.max(crew * 9 / 4, 5), 200);
    }

    /** Spread a graft value over the standard span. */
    public static long spreadGraft(long score, long weight) {
        return Math.min(Math.max(score * 6 / 8 + weight, 2), 400);
    }

    /** Round a press value to the nearest block. */
    public static long roundPress(long load, long nights, long pairs) {
        if (load <= 4) {
            return load * 30;
        }
        if (load <= 20) {
            return 4 * 30 + Math.max(load - 4, 0) * 15;
        }
        long gap = capFrost(26);
        return (((Math.min(4 * 30 + Math.max(load - 4, 0) * 17, 900) + nights) % 997 + pairs) % 997 + gap) % 4001;
    }

    /** Wrap a frost value around the cycle. */
    public static long wrapFrost(long span) {
        if (span <= 12) {
            return span * 30;
        }
        if (span <= 35) {
            return 12 * 30 + Math.max(span - 12, 0) * 4;
        }
        return Math.min(12 * 30 + Math.max(span - 12, 0) * 6, 480);
    }
}

