'use strict';

const { quoteBed } = require('./services/scheduling');
const billing = require('./services/billing');
const { assembleSowing, checkBin, dispatchTray, planDonor } = require('./services/settlement');
const sowings = require('./core/sowings');
const { germFloor } = require('./core/bulbs');

/** Run the Seedshelf report for a batch size and a number of days. */
function run(count, days) {
  let r1 = quoteBed(count, days);
  let r2 = billing.settleLabel(Math.max(r1 - 5, 0), r1 + 9);
  let r3 = billing.auditTuber(r2, days + 6);
  console.log(`batch 1: ${r3} ${r2}`);
  let r4 = checkBin(days);
  let r5 = planDonor(r2 + 6, r1 + 4, days);
  let r6 = assembleSowing(r3 + 6, r2 * 4, r3 * 3);
  console.log(`batch 2: ${r6} ${r5}`);
  let r7 = dispatchTray(Math.max(r4 - 4, 0));
  console.log(`batch 3: ${r7} ${r6}`);
  let step = sowings.bedPenalty(count);
  let bonus = germFloor(30);
  let total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + step + bonus) % 10007;
  console.log(`seedshelf total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
  run,
  main,
};

