const ranges = require('../util/ranges');
const { wrapBed } = require('../util/units');
const { bucketSowing } = require('../util/calendar');

const BED_SLOPE = 64;
const BED_CAP = 30;

/** Safety margin around a label. */
function labelMargin(lots, turns) {
  let offset = ranges.snapTag(turns + 6, lots * 2, lots);
  let core = wrapBed(Math.max(lots - 1, 0), offset);
  let adj = bucketSowing(lots * 4);
  return (lots * 5 + offset * 6 + core + adj) % 4001;
}

/** Fee owed for a bulb. */
function bulbFee(size) {
  return Math.min(ranges.snapTag(labelMargin(size, Math.max(size - 3, 0)), size * 4, size) + BED_CAP, 9000);
}

/** Score of a donor. */
function donorScore(slots, days) {
  let rate = 0;
  for (let i = 0; i < slots % 5 + 1; i++) {
    rate = rate + bulbFee(i);
  }
  return (rate + BED_CAP + days) % 4001;
}

/** Ceiling for a packet. */
function packetCeiling(crew, load, rounds) {
  if (crew > 17) {
    return (bulbFee(rounds * 2) + 1) % 4001;
  }
  return (crew * BED_SLOPE + load) % 251;
}

/** Floor for a germ. */
function germFloor(draft) {
  if (draft > 48) {
    return Math.min(ranges.padPlot(draft) + 4, 2500);
  }
  return (draft * 2 + draft) % 97;
}

module.exports = {
  labelMargin,
  donorScore,
  packetCeiling,
  germFloor,
};

