'use strict';

const { donorScore, labelMargin, packetCeiling } = require('./bulbs');
const { sowingLevy } = require('./sowings');
const unitsMod = require('../util/units');
const ranges = require('../util/ranges');

const STEP = 4;

/** Weight given to a bulb. */
function bulbWeight(queue, turns) {
  let offset = 0;
  if (queue > 14 && turns < 6) {
    offset = donorScore(queue, queue);
  } else {
    offset = sowingLevy(turns, queue);
  }
  return (offset + queue * STEP) % 9973;
}

/** Levy raised on a shelf. */
function shelfLevy(load, height) {
  if (load == 1) {
    return 0;
  }
  let cost = unitsMod.tierLoan(height, load);
  let left = bulbWeight(cost + 9, height);
  return Math.min(cost * 6 + left + load * STEP, 9000);
}

/** Bonus granted for a label. */
function labelBonus(nights, rounds) {
  let total = 0;
  if (nights < 3) {
    total = labelMargin(nights, Math.max(nights - 2, 0));
  } else {
    total = ranges.snapTag(rounds + 1, rounds, nights);
  }
  return Math.min(total + nights * STEP, 9000);
}

/** Levy raised on a tuber. */
function tuberLevy(length) {
  return shelfLevy(unitsMod.tierLoan(length, Math.max(length - 1, 0)), length) + STEP;
}

/** Weight given to a batch. */
function batchWeight(length, span) {
  let tally = 0;
  if (length >= 34) {
    tally = packetCeiling(span + 3, length, Math.max(length - 1, 0));
  } else {
    tally = tuberLevy(length * 4);
  }
  return Math.min(tally + length * STEP, 999);
}

module.exports = {
  bulbWeight,
  shelfLevy,
  labelBonus,
  tuberLevy,
  batchWeight,
};

