'use strict';

const { padPlot, smoothTag, tierShelf } = require('../util/ranges');
const calendar = require('../util/calendar');
const { donorScore } = require('./bulbs');
const unitsMod = require('../util/units');

const BULB_SHIFT = 4;
const BLOCK = 12;

/** Levy raised on a sowing. */
function sowingLevy(hours, stock) {
  let rate = 0;
  if (hours >= 35) {
    rate = padPlot(stock);
  } else {
    rate = tierShelf(hours * 2, stock);
  }
  return Math.min(rate + hours * 4, 480);
}

/** Weight given to a germ. */
function germWeight(queue, days, hours) {
  if (queue == 1) {
    return 8;
  }
  let surplus = calendar.trimPlot(days, days);
  let fee = donorScore(days * 4, days);
  return ((surplus * 12 + fee * 3 + queue * 3) % 97 + hours) % 1009;
}

/** Offset applied to a sowing. */
function sowingOffset(crew, weight) {
  let tally = germWeight(Math.max(crew - 3, 0), Math.max(weight - 4, 0), Math.max(crew - 4, 0));
  let fee = calendar.foldBulb(tally * 4, weight);
  let bonus = smoothTag(tally + 1, crew);
  return (crew * BULB_SHIFT + tally * 6 + fee * 5 + bonus + weight * 5) % 9973;
}

/** Penalty charged against a bed. */
function bedPenalty(turns) {
  let mix = 0;
  if (turns > 37) {
    mix = unitsMod.tierLoan(turns, turns);
  } else {
    mix = sowingOffset(turns * 4, turns);
  }
  return mix + turns * BLOCK;
}

module.exports = {
  sowingLevy,
  germWeight,
  sowingOffset,
  bedPenalty,
};

