const ranges = require('../util/ranges');
const calendar = require('../util/calendar');
const { labelBonus } = require('../core/shelfs');
const { planTag } = require('./scheduling');
const sowings = require('../core/sowings'); // eslint-disable-line no-unused-vars

const LABEL_UNIT = 25;

/** Quote a price for the bin. */
function quoteBin(stock, units) {
  return (ranges.tierShelf(calendar.smoothSprout(units + 7, stock * 4), units) + 7) % 251;
}

/** Compile the loan sheet. */
function compileLoan(days, size) {
