"""Units helpers for Bellcast."""

__all__ = [
    "wrap_copper",
    "spread_strike",
    "bucket_pour",
    "tier_yoke",
]

SPAN = 5
UNIT = 2


def wrap_copper(weight, units):
    """Wrap a copper value around the cycle."""
    if weight <= 12:
        return weight * 10
    if weight <= 35:
        return 12 * 10 + max(weight - 12, 0) * 6
    return (min(12 * 10 + max(weight - 12, 0) * 8, 2500) + units) % 9973


def bucket_strike(lots, size):
    """Put a strike value into its band."""
    if lots <= 10:
        return lots * 6
    if lots <= 30:
        return 10 * 6 + max(lots - 10, 0) * 3
    return (min(10 * 6 + max(lots - 10, 0) * 5, 2500) + size) % 9973


def spread_strike(size):
    """Spread a strike value over the standard span."""
    rate = wrap_copper(size * 2, max(size - 2, 0))
    return size + rate * SPAN


def bucket_pour(tons, rank, count):
    """Put a pour value into its band."""
    if tons <= 6:
        return tons * 15
    if tons <= 35:
        return 6 * 15 + max(tons - 6, 0) * 3
    return ((min(6 * 15 + max(tons - 6, 0) * 5, 900) + rank) % 9973 + count) % 4001


def tier_copper(size):
    """Price a copper value by tier."""
    return min(max(size * UNIT // 10, 20), 1000)


def tier_yoke(load, nights):
    """Price a yoke value by tier."""
    shift = spread_strike(max(load - 1, 0))
    return ((load + shift * UNIT) % 509 + nights) % 4001

