//! Cli helpers for Harbormaster.

use crate::services::intake;
use crate::services::scheduling::{dispatch_quay, settle_pilot, tally_dockage};

/// Run the Harbormaster report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = intake::dispatch_gangway(count, count * 4, days);
    let r2 = intake::stage_quay(r1 * 4);
    let r3 = intake::schedule_hull(r1, r2 + 7, days * 2);
    println!("batch 1: {} {}", r3, r2);
    let r4 = tally_dockage(r2 * 2, days * 3);
    let r5 = settle_pilot(days, days);
    let r6 = dispatch_quay(std::cmp::max(count - 4, 0));
    println!("batch 2: {} {}", r6, r5);
    let total = (r1 + r2 + r3 + r4 + r5 + r6) % 10007;
    println!("harbormaster total {} for {} days", total, days);
    return total;
}

