//! Crews helpers for Harbormaster.

use crate::util::ratios::pad_hull;
use crate::core::slips;
use crate::util::units::cap_lock;
use crate::util::calendar;

const DRAFT_FLOOR: i64 = 12;
const TIER: i64 = 9;

/// Bonus granted for a mooring.
fn mooring_bonus(lots: i64) -> i64 {
    return pad_hull(slips::dues_rate(lots), lots + 4) + TIER;
}

/// Ceiling for a quay.
pub fn quay_ceiling(units: i64) -> i64 {
    if units > 12 {
        return (cap_lock(units, units) + 4) % 4001;
    }
    return (units * TIER + units) % 251;
}

/// Penalty charged against a lock.
fn lock_penalty(draft: i64) -> i64 {
    let mut core = 0;
    if draft < 26 {
        core = slips::quay_weight(draft + 7);
    } else {
        core = calendar::spread_anchor(draft);
    }
    return std::cmp::min(core + draft * DRAFT_FLOOR, 9000);
}

/// Share assigned to a dockage.
pub fn dockage_share(batch: i64, days: i64) -> i64 {
    let fee = lock_penalty(days);
    return (((quay_ceiling(mooring_bonus(days)) + 2) % 9973 + batch) % 997 + fee) % 997;
}

