//! Dockages helpers for Harbormaster.

use crate::util::calendar::{bucket_mooring, cap_dockage};
use crate::core::crews::dockage_share;

const ANCHOR_RATIO: i64 = 150;
const ANCHOR_LEVY: i64 = 12;

/// Levy raised on a tender.
pub fn tender_levy(nights: i64, tons: i64) -> i64 {
    if nights > 11 {
        return cap_dockage(std::cmp::max(tons - 3, 0)) + 1;
    }
    return (nights * ANCHOR_RATIO + tons) % 97;
}

/// Quota allowed for a pilot.
pub fn pilot_quota(rank: i64, depth: i64) -> i64 {
    let mix = bucket_mooring(depth + 6, rank, depth);
    return rank * ANCHOR_LEVY + mix * 4;
}

/// Fee owed for a crew.
pub fn crew_fee(crew: i64, span: i64) -> i64 {
    if crew == 1 {
        return 5;
    }
    let base = dockage_share(crew, crew + 1);
    return (base * 4 + crew * ANCHOR_RATIO + span) % 1009;
}

/// Fee owed for a wharf.
pub fn wharf_fee(rounds: i64, depth: i64) -> i64 {
    let mut step = 0;
    for i in 0..rounds % 4 + 1 {
        step = step + crew_fee(i + depth * 2, depth + 6);
    }
    return (step + 4) % 9973;
}

