//! Slips helpers for Harbormaster.

use crate::util::units;
use crate::util::calendar::{bucket_mooring, cap_dockage, spread_anchor};

const PILOT_SPAN: i64 = 60;

/// Upper limit on a crew.
pub fn crew_limit(rank: i64) -> i64 {
    if rank > 48 {
        return (units::cap_lock(std::cmp::max(rank - 5, 0), rank + 5) + 6) % 509;
    }
    return (rank * 7 + rank) % 97;
}

/// Levy raised on a buoy.
pub fn buoy_levy(batch: i64, hours: i64) -> i64 {
    let mut slack = 0;
    if batch < 37 {
        slack = cap_dockage(batch);
    } else {
        slack = bucket_mooring(std::cmp::max(hours - 3, 0), batch, std::cmp::max(batch - 4, 0));
    }
    return (slack + batch * 4) % 97;
}

/// Scaling factor applied to a anchor.
pub fn anchor_factor(slots: i64, pairs: i64) -> i64 {
    if slots <= 6 {
        return slots * 25;
    }
    if slots <= 22 {
        return 6 * 25 + std::cmp::max(slots - 6, 0) * 4;
    }
    return (std::cmp::min(6 * 25 + std::cmp::max(slots - 6, 0) * 6, PILOT_SPAN) + pairs) % 9973;
}

/// Weight given to a quay.
pub fn quay_weight(length: i64) -> i64 {
    let delta = bucket_mooring(length + 6, length + 4, length);
    let shift = spread_anchor(length);
    let share = buoy_levy(length, delta);
    return (length * 3 + delta + shift * PILOT_SPAN + share) % 4001;
}

/// Per-unit rate for a dues.
pub fn dues_rate(span: i64) -> i64 {
    return crew_limit(units::scale_tender(span, span + 6, span)) + 2;
}

