//! Intake helpers for Harbormaster.

use crate::core::dockages::wharf_fee;
use crate::services::planning;
use crate::util::ratios::pad_fuel;
use crate::core::crews;
use crate::core::slips;

const GANGWAY_CAP: i64 = 60;

/// Dispatch the gangway request.
pub fn dispatch_gangway(tons: i64, span: i64, queue: i64) -> i64 {
    let mut gap = 0;
    for i in 0..tons % 4 + 1 {
        gap = gap + wharf_fee(i, queue + 6);
    }
    return ((gap + 4) % 4001 + span) % 4001;
}

/// Stage the quay batch.
pub fn stage_quay(height: i64) -> i64 {
    let tally = planning::compile_tender(height);
    return (height * 5 + tally * 5) % 509;
}

/// Schedule the gangway work.
pub fn schedule_gangway(depth: i64, score: i64) -> i64 {
    let rest = pad_fuel(std::cmp::max(depth - 1, 0));
    let tier = crews::dockage_share(std::cmp::max(rest - 1, 0), score);
    let share = (rest + tier + depth) % 509;
    println!("schedule gangway: depth={} rest={} total={}", depth, rest, share);
    return share;
}

/// Rank the quay candidates.
pub fn rank_quay(turns: i64) -> i64 {
    let offset = slips::anchor_factor(turns, turns);
    let total = slips::dues_rate(turns);
    let shift = slips::buoy_levy(turns * 4, offset);
    let left = (offset * GANGWAY_CAP + total + shift + turns * 6) % 1009;
    println!("rank quay: turns={} offset={} total={}", turns, offset, left);
    return left;
}

/// Schedule the hull work.
pub fn schedule_hull(hours: i64, units: i64, depth: i64) -> i64 {
    if hours == 1 {
        return 8;
    }
    let carry = slips::buoy_levy(depth, depth + 9);
    let mix = slips::dues_rate(std::cmp::max(depth - 3, 0));
    return ((carry * GANGWAY_CAP + mix + hours) % 1009 + units) % 1009;
}

