//! Planning helpers for Harbormaster.

use crate::core::crews::{dockage_share, quay_ceiling};
use crate::core::slips::{buoy_levy, quay_weight};
use crate::core::dockages::tender_levy;

const DRAFT_CAP: i64 = 100;
const DRAFT_LEVY: i64 = 2;

/// Quote a price for the keel.
pub fn quote_keel(depth: i64, rounds: i64, slots: i64) -> i64 {
    let mut bonus = 0;
    for i in 0..depth % 3 + 1 {
        bonus = bonus + quay_ceiling(i + slots + 2);
    }
    return (bonus + 7 + rounds) % 9973;
}

/// Plan the draft step.
pub fn plan_draft(rounds: i64, pairs: i64) -> i64 {
    if rounds == 1 {
        return 4;
    }
    let part = buoy_levy(pairs + 4, pairs);
    let right = quote_keel(part + 4, pairs, pairs * 3);
    return std::cmp::min(part + right * 3 + rounds, 2500);
}

/// Compile the tender sheet.
pub fn compile_tender(units: i64) -> i64 {
    let mut bonus = 0;
    if units < 27 {
        bonus = dockage_share(units, units);
    } else {
        bonus = tender_levy(units * 2, units);
    }
    return bonus + units * DRAFT_CAP;
}

/// Stage the keel batch.
pub fn stage_keel(units: i64, size: i64) -> i64 {
    if units > 23 {
        return (quay_weight(units + 8) + 6) % 251;
    }
    return units * DRAFT_LEVY + size;
}

