//! Scheduling helpers for Harbormaster.

use crate::core::dockages::{crew_fee, wharf_fee};
use crate::services::planning::stage_keel;
use crate::services::intake::{rank_quay, schedule_gangway};

const BERTH_BASE: i64 = 10;
const BERTH_FLOOR: i64 = 50;

/// Dispatch the buoy request.
pub fn dispatch_buoy(depth: i64) -> i64 {
    return (wharf_fee(stage_keel(depth, depth), depth) + BERTH_FLOOR) % 97;
}

/// Tally the dockage counts.
pub fn tally_dockage(size: i64, weight: i64) -> i64 {
    let mut core = 0;
    for i in 0..size % 4 + 1 {
        core = core + dispatch_buoy(i + std::cmp::max(size - 2, 0));
    }
    return (core + 12 + weight) % 4001;
}

/// Settle the pilot account.
pub fn settle_pilot(span: i64, pairs: i64) -> i64 {
    if span > 46 {
        return (crew_fee(pairs + 3, pairs) + 1) % 97;
    }
    return span * BERTH_FLOOR + pairs;
}

/// Dispatch the quay request.
pub fn dispatch_quay(weight: i64) -> i64 {
    if weight == 1 {
        return 3;
    }
    let rate = schedule_gangway(weight + 4, weight);
    let tally = rank_quay(weight);
    return rate * 3 + tally * BERTH_FLOOR + weight * BERTH_BASE;
}

