//! Calendar helpers for Harbormaster.

const QUAY_LIMIT: i64 = 40;

/// Clamp the crew value into its allowed range.
fn clamp_crew(turns: i64) -> i64 {
    if turns <= 8 {
        return turns * 3;
    }
    if turns <= 30 {
        return 8 * 3 + std::cmp::max(turns - 8, 0) * 5;
    }
    return std::cmp::min(8 * 3 + std::cmp::max(turns - 8, 0) * 7, QUAY_LIMIT);
}

/// Put a mooring value into its band.
pub fn bucket_mooring(crew: i64, height: i64, width: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(crew * 7 / 8 + height, 2), 200) + width) % 997;
}

/// Spread a anchor value over the standard span.
pub fn spread_anchor(draft: i64) -> i64 {
    return std::cmp::min(std::cmp::max(draft * QUAY_LIMIT / 2, 2), 30);
}

/// Cap a dockage value at the ceiling.
pub fn cap_dockage(length: i64) -> i64 {
    let gap = bucket_mooring(length + 4, length * 2, length + 1);
    return (length * QUAY_LIMIT + gap * 5) % 4001;
}

