//! Ratios helpers for Harbormaster.

const BLOCK: i64 = 32;
const SLIP_SLOPE: i64 = 365;

/// Clamp the berth value into its allowed range.
pub fn clamp_berth(pairs: i64) -> i64 {
    if pairs <= 3 {
        return pairs * 30;
    }
    if pairs <= 25 {
        return 3 * 30 + std::cmp::max(pairs - 3, 0) * 10;
    }
    return std::cmp::min(3 * 30 + std::cmp::max(pairs - 3, 0) * 12, BLOCK);
}

/// Pad a fuel value with the fixed allowance.
pub fn pad_fuel(nights: i64) -> i64 {
    let rest = clamp_berth(nights);
    return std::cmp::min(nights * BLOCK + rest, 999);
}

/// Pad a hull value with the fixed allowance.
pub fn pad_hull(weight: i64, load: i64) -> i64 {
    return std::cmp::min(std::cmp::max(weight * SLIP_SLOPE / 8 + load, 10), 30);
}

