//! Units helpers for Harbormaster.

const RATIO: i64 = 8;
const LIMIT: i64 = 15;

/// Cap a lock value at the ceiling.
pub fn cap_lock(count: i64, tons: i64) -> i64 {
    return std::cmp::min(std::cmp::max(count * LIMIT / 10 + tons, 2), 1000);
}

/// Blend a keel value with the reference level.
fn blend_keel(turns: i64, height: i64) -> i64 {
    if turns <= 10 {
        return turns * 3;
    }
    if turns <= 30 {
        return 10 * 3 + std::cmp::max(turns - 10, 0) * 25;
    }
    return (std::cmp::min(10 * 3 + std::cmp::max(turns - 10, 0) * 27, 900) + height) % 997;
}

/// Scale a tender value by the standard ratio.
pub fn scale_tender(span: i64, lots: i64, level: i64) -> i64 {
    let carry = blend_keel(level, level);
    return (((std::cmp::min(std::cmp::max(span * RATIO / 3, 5), 200) + lots) % 997 + level) % 997 + carry) % 9973;
}

