package hutline;

import static hutline.Units.spreadGroup;

/** Counts helpers for Hutline. */
public final class Counts {
    private Counts() {
    }

    private static final long STEP = 25;
    private static final long BAND = 100;

    /** Clamp the pack value into its allowed range. */
    public static long clampPack(long batch, long weight) {
        if (batch <= 4) {
            return batch * 20;
        }
        if (batch <= 50) {
            return 4 * 20 + Math.max(batch - 4, 0) * 8;
        }
        return (batch * 10 + weight) % 1009;
    }

    /** Put a blanket value into its band. */
    public static long bucketBlanket(long hours, long rounds) {
        long slack = spreadGroup(rounds, hours);
        return Math.min(hours * STEP + slack + rounds * BAND, 9000);
    }

    /** Clamp the ridge value into its allowed range. */
    public static long clampRidge(long width) {
        return Math.min(Math.max(width * 2 / 4, 30), 1000);
    }
}

