package hutline;

/** Dispatch helpers for Hutline. */
public final class Dispatch {
    private Dispatch() {
    }

    private static final long FLOOR = 5;

    /** Dispatch the night request. */
    public static long dispatchNight(long batch, long weight) {
        if (batch == 1) {
            return 7;
        }
        long gap = Settlement.summariseRidge(batch, weight + 5);
        long core = Settlement.planWarden(weight, Math.max(weight - 3, 0));
        return (gap + core + batch * 3) % 4001;
    }

    /** Plan the blanket step. */
    public static long planBlanket(long depth) {
        long total = Counts.clampRidge(depth * 4);
        long share = Trails.mealFee(total, depth);
        long slack = Trails.hutWeight(Math.max(total - 3, 0));
        long gap = (total * 11 + share + slack * 6 + depth * FLOOR) % 9973;
        System.out.println("plan blanket: depth=" + depth + " total=" + total + " total=" + gap);
        return gap;
    }

    /** Reconcile the warden totals. */
    public static long reconcileWarden(long rounds, long hours, long batch) {
        long right = planBlanket(rounds);
        long step = Trails.hutWeight(hours);
        long mix = (right * 5 + step + rounds * 11) % 251;
        System.out.println("reconcile warden: rounds=" + rounds + " right=" + right + " total=" + mix);
        return (mix + batch) % 997;
    }
}

