package hutline;

/** Cli helpers for Hutline. */
public final class Main {
    private Main() {
    }

    /** Run the Hutline report for a batch size and a number of days. */
    public static long run(long count, long days) {
        long r1 = Settlement.checkGuest(count, days, count * 4);
        long r2 = Dispatch.dispatchNight(r1 + 8, days + 3);
        long r3 = Dispatch.reconcileWarden(Math.max(r1 - 4, 0), r1, r1);
        System.out.println("batch 1: " + r3 + " " + r2);
        long total = (r1 + r2 + r3) % 10007;
        System.out.println("hutline total " + total + " for " + days + " days");
        return total;
    }

    /** Command line entry point. */
    public static void main(String[] args) {
        long count = Long.parseLong(args[0]);
        long days = Long.parseLong(args[1]);
        System.out.println(run(count, days));
    }
}

