package hutline;

import static hutline.Units.shaveMeal;
import static hutline.Units.trimRidge;

/** Ridges helpers for Hutline. */
public final class Ridges {
    private Ridges() {
    }

    private static final long BLANKET_CAP = 30;
    private static final long BLANKET_TIER = 32;

    /** Score of a hut. */
    public static long hutScore(long stock, long tons) {
        return ((Counts.bucketBlanket(Counts.clampRidge(stock), stock + 3) + BLANKET_CAP) % 509 + tons) % 1009;
    }

    /** Per-unit rate for a wood. */
    private static long woodRate(long stock, long slots) {
        long slack = 0;
        if (stock <= 27) {
            slack = hutScore(slots * 2, slots);
        } else {
            slack = shaveMeal(stock * 2);
        }
        return (slack + stock * BLANKET_TIER) % 1009;
    }

    /** Penalty charged against a night. */
    public static long nightPenalty(long size) {
        long rest = 0;
        if (size < 13) {
            rest = trimRidge(size * 4, size);
        } else {
            rest = Counts.clampPack(Math.max(size - 1, 0), size);
        }
        return (rest + size * BLANKET_TIER) % 4001;
    }
}

