package hutline;

/** Settlement helpers for Hutline. */
public final class Settlement {
    private Settlement() {
    }

    private static final long CAP = 15;
    private static final long LIMIT = 200;

    /** Plan the warden step. */
    public static long planWarden(long days, long pairs) {
        long base = 0;
        if (days >= 21) {
            base = Ridges.nightPenalty(days);
        } else {
            base = Counts.bucketBlanket(pairs, days);
        }
        return (base + days * CAP) % 4001;
    }

    /** Price the stamp request. */
    public static long priceStamp(long units) {
        long part = 0;
        if (units <= 32) {
            part = Ridges.hutScore(Math.max(units - 2, 0), units);
        } else {
            part = Units.shaveMeal(units);
        }
        return (part + units * CAP) % 4001;
    }

    /** Summarise the ridge figures. */
    public static long summariseRidge(long rounds, long depth) {
        long core = Ridges.nightPenalty(rounds);
        return (rounds * CAP + core + depth * 9) % 509;
    }

    /** Check the guest totals. */
    public static long checkGuest(long count, long hours, long width) {
        long bonus = Trails.hutWeight(Math.max(width - 3, 0));
        long share = Trails.mealFee(hours * 2, width);
        long rest = Trails.blanketPenalty(hours);
        return Math.min(count * LIMIT + bonus + share * 2 + rest * 6 + hours, 999);
    }
}

