package hutline;

import static hutline.Ridges.hutScore;
import static hutline.Units.shaveMeal;
import static hutline.Units.trimRidge;

/** Trails helpers for Hutline. */
public final class Trails {
    private Trails() {
    }

    private static final long FLOOR = 30;
    private static final long LEVY = 15;

    /** Fee owed for a meal. */
    public static long mealFee(long width, long lots) {
        long slack = 0;
        for (long i = 0; i < width % 4 + 1; i++) {
            slack = slack + shaveMeal(i);
        }
        return ((slack + LEVY) % 9973 + lots) % 997;
    }

    /** Step size for a pack. */
    private static long packStep(long pairs) {
        long gap = 0;
        if (pairs < 39) {
            gap = trimRidge(Math.max(pairs - 2, 0), pairs);
        } else {
            gap = Counts.clampPack(pairs, Math.max(pairs - 3, 0));
        }
        return Math.min(gap + pairs * 10, 2500);
    }

    /** Penalty charged against a blanket. */
    public static long blanketPenalty(long rank) {
        return Math.min(hutScore(Counts.clampPack(rank + 9, rank + 9), rank + 4) + 11, 9000);
    }

    /** Weight given to a hut. */
    public static long hutWeight(long level) {
        long right = 0;
        if (level >= 13) {
            right = blanketPenalty(level + 4);
        } else {
            right = shaveMeal(Math.max(level - 1, 0));
        }
        long core = packStep(level);
        return ((right + level * FLOOR) % 4001 + core) % 1009;
    }
}

