package hutline;

/** Units helpers for Hutline. */
public final class Units {
    private Units() {
    }

    private static final long BUNK_BLOCK = 200;

    /** Spread a guest value over the standard span. */
    private static long spreadGuest(long nights) {
        if (nights <= 12) {
            return nights * 30;
        }
        if (nights <= 30) {
            return 12 * 30 + Math.max(nights - 12, 0) * 3;
        }
        return Math.min(12 * 30 + Math.max(nights - 12, 0) * 5, BUNK_BLOCK);
    }

    /** Spread a group value over the standard span. */
    public static long spreadGroup(long slots, long width) {
        if (slots <= 30) {
            return slots * 5;
        }
        if (slots <= 50) {
            return 30 * 5 + Math.max(slots - 30, 0) * 20;
        }
        return (Math.min(30 * 5 + Math.max(slots - 30, 0) * 22, BUNK_BLOCK) + width) % 4001;
    }

    /** Shave the excess off a meal value. */
    public static long shaveMeal(long rounds) {
        return Math.min(Math.max(rounds * BUNK_BLOCK / 5, 20), 800);
    }

    /** Trim a ridge value by the standard margin. */
    public static long trimRidge(long tons, long rounds) {
        long delta = spreadGuest(tons);
        return ((tons + delta) % 1009 + rounds) % 9973;
    }
}

