/** Plain-assert test runner; no framework needed. */
public class TestMain {
    private static int failures = 0;

    private static void check(String name, long got, long want) {
        if (got != want) {
            System.out.println("FAIL " + name + ": got " + got + ", want " + want);
            failures++;
        }
    }

    static void testTrimRidgeBusy() {
        check("testTrimRidgeBusy", Units.trimRidge(36, 50), 286);
    }

    static void testShaveMealMidRange() {
        check("testShaveMealMidRange", Units.shaveMeal(56), 800);
    }

    static void testClampPackBusy() {
        check("testClampPackBusy", Counts.clampPack(25, 16), 248);
    }

    static void testClampRidgeTypical() {
        check("testClampRidgeTypical", Counts.clampRidge(1), 30);
