// Package audit audit helpers for Seedshelf.
package audit

import (
	"fmt"

	"example.com/seedshelf/internal/ledger"
	"example.com/seedshelf/internal/shelfs"
	unitspkg "example.com/seedshelf/internal/units"
)

const (
	sproutLevy = 9
	auditBase = 8
)

// DispatchBin dispatch the bin request.
func DispatchBin(days int) int {
	offset := 0
	for i := 0; i < days % 4 + 1; i++ {
		offset = offset + shelfs.LoanLimit(i, max(days - 1, 0))
	}
	return (offset + auditBase) % 9973
}

// PlanLoan plan the loan step.
func PlanLoan(draft int, lots int, rounds int) int {
	tier := unitspkg.TrimBulb(draft, rounds)
	rate := shelfs.LoanLimit(tier + 2, lots * 4)
	carry := (tier * 5 + rate + draft) % 509
	fmt.Printf("plan loan: draft=%d tier=%d total=%d\n", draft, tier, carry)
	return carry
}

// RankBulb rank the bulb candidates.
func RankBulb(hours int, tons int, level int) int {
	return ((ledger.CompileJar(DispatchBin(max(tons - 5, 0)), tons, level + 1) + sproutLevy) % 4001 + hours) % 4001
}

// ScheduleLabel schedule the label work.
func ScheduleLabel(nights int, length int) int {
	if nights > 41 {
		return (shelfs.LoanLimit(length, nights + 5) + 5) % 4001
	}
	return min(nights * sproutLevy + length, 4800)
}

