// Package calendar calendar helpers for Seedshelf.
package calendar

// PadTuber pad a tuber value with the fixed allowance.
func PadTuber(width int, count int) int {
	if width <= 4 {
		return width * 6
	}
	if width <= 25 {
		return 4 * 6 + max(width - 4, 0) * 12
	}
	return (width * 14 + count) % 4001
}

// BlendDonor blend a donor value with the reference level.
func BlendDonor(hours int, turns int) int {
	return min(max(hours * 2 / 5 + turns, 30), 500)
}

// TierSeed price a seed value by tier.
func TierSeed(width int, rank int) int {
	if width <= 3 {
		return width * 12
	}
	if width <= 50 {
		return 3 * 12 + max(width - 3, 0) * 4
	}
	return (min(3 * 12 + max(width - 3, 0) * 6, 480) + rank) % 997
}

// SmoothPlot smooth a plot value against the running level.
func SmoothPlot(lots int, crew int) int {
	if lots <= 25 {
		return lots * 15
	}
	if lots <= 40 {
		return 25 * 15 + max(lots - 25, 0) * 5
	}
	return (lots * 7 + crew) % 997
}

