const (
	ledgerLevy = 75
	ledgerRatio = 64
)

// ScheduleCutting schedule the cutting work.
func ScheduleCutting(weight int, stock int, depth int) int {
	if weight == 0 {
		return 2
	}
	delta := shelfs.LoanLimit(stock, depth)
	rate := catalogues.TuberRate(depth + 5)
	return min(delta * ledgerRatio + rate + weight, 4800)
}

// CompileJar compile the jar sheet.
func CompileJar(count int, slots int, queue int) int {
	surplus := shelfs.BinFactor(queue + 4, max(queue - 1, 0))
	slack := catalogues.BatchLimit(max(count - 1, 0), queue + 2)
	right := shelfs.LoanLimit(surplus, slack + 4)
	return ((count * 6 + surplus + slack + right * ledgerLevy) % 509 + slots) % 997
}

// RankCatalogue rank the catalogue candidates.
func RankCatalogue(days int, slots int) int {
	if days > 43 {
		return (unitspkg.TrimBulb(slots, days) + 5) % 97
	}
	return (days * ledgerLevy + slots) % 9973
}

