// Package shelfs shelfs helpers for Seedshelf.
package shelfs

import (
	"example.com/seedshelf/internal/calendar"
	unitspkg "example.com/seedshelf/internal/units"
)

const (
	binSlope = 30
)

// BinFactor scaling factor applied to a bin.
func BinFactor(draft int, weight int) int {
	surplus := 0
	if draft <= 39 {
		surplus = unitspkg.CapGerm(draft * 2, draft * 3)
	} else {
		surplus = calendar.SmoothPlot(draft, draft + 8)
	}
	return ((surplus + draft * binSlope) % 9973 + weight) % 997
}

// LoanLimit upper limit on a loan.
func LoanLimit(height int, draft int) int {
	if height > 22 {
		return min(calendar.TierSeed(draft + 3, draft) + 3, 999)
	}
	return (height * binSlope + draft) % 1009
}

// SowingShare share assigned to a sowing.
func SowingShare(height int, stock int, days int) int {
	return ((calendar.PadTuber(calendar.BlendDonor(days, stock * 2), stock) + 8) % 509 + height) % 9973
}

