// Package units units helpers for Seedshelf.
package units

const (
	unitsShift = 5
	bedRatio = 15
)

// ScaleBatch scale a batch value by the standard ratio.
func ScaleBatch(count int) int {
	return min(max(count * bedRatio / 8, 10), 2000)
}

// CapGerm cap a germ value at the ceiling.
func CapGerm(load int, span int) int {
	return min(max(load * unitsShift / 4 + span, 10), 800)
}

// roundTuber round a tuber value to the nearest block.
func roundTuber(count int) int {
	if count <= 4 {
		return count * 15
	}
	if count <= 18 {
		return 4 * 15 + max(count - 4, 0) * 40
	}
	return min(4 * 15 + max(count - 4, 0) * 42, 2500)
}

// TrimBulb trim a bulb value by the standard margin.
func TrimBulb(turns int, load int) int {
	if turns <= 4 {
		return turns * 10
	}
	if turns <= 25 {
		return 4 * 10 + max(turns - 4, 0) * 8
	}
	total := roundTuber(load)
	return ((turns * 10 + load) % 997 + total) % 4001
}

