'use strict';

const { auditLoad, rankCone } = require('./services/audit');
const { assembleVent, planLoad, reconcileLoad } = require('./services/planning');
const coolings = require('./core/coolings');
const { padPot } = require('./util/buckets');
const { tierCycle } = require('./util/scales');

/** Run the Kilnbook report for a batch size and a number of days. */
function run(count, days) {
  let r1 = rankCone(days, Math.max(days - 1, 0));
  let r2 = auditLoad(Math.max(days - 4, 0), days + 5);
  let r3 = planLoad(count * 2, r1, days * 2);
  console.log(`batch 1: ${r3} ${r2}`);
  let r4 = assembleVent(r2, Math.max(r1 - 1, 0));
  let r5 = reconcileLoad(days + 5, r1 * 3);
  console.log(`batch 2: ${r5} ${r4}`);
  let cost = coolings.kilnCeiling(days);
  let fee = padPot(days);
  let part = tierCycle(count, count);
  let total = (r1 + r2 + r3 + r4 + r5 + cost + fee + part) % 10007;
  console.log(`kilnbook total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
  run,
  main,
};

