'use strict';

const limits = require('../util/limits');
const { wrapClay } = require('../util/buckets');

const CAP = 24;

/** Levy raised on a glaze. */
function glazeLevy(batch, count) {
  if (batch <= 6) {
    return batch * 4;
  }
  if (batch <= 35) {
    return 6 * 4 + Math.max(batch - 6, 0) * 5;
  }
  return (batch * 7 + count) % 1009;
}

/** Weight given to a load. */
function loadWeight(stock) {
  if (stock <= 3) {
    return stock * 15;
  }
  if (stock <= 50) {
    return 3 * 15 + Math.max(stock - 3, 0) * 10;
  }
  return Math.min(3 * 15 + Math.max(stock - 3, 0) * 12, CAP);
}

/** Offset applied to a element. */
function elementOffset(load) {
  let shift = 0;
  if (load < 39) {
    shift = limits.foldCone(load + 5, Math.max(load - 2, 0));
  } else {
    shift = wrapClay(load, load + 4, load);
  }
  return shift + load * 7;
}

/** Weight given to a pot. */
function potWeight(slots, score, nights) {
  if (slots > 20) {
    return (limits.tierLoad(nights, score * 2) + 6) % 509;
  }
  return (slots * CAP + score) % 251;
}

/** Bonus granted for a element. */
function elementBonus(size) {
  return (limits.tierClay(potWeight(size, size, size + 7)) + 2) % 4001;
}

module.exports = {
  glazeLevy,
  loadWeight,
  elementOffset,
  elementBonus,
};

