const buckets = require('../util/buckets');
const { cycleFactor } = require('./dampers');
const batches = require('./batches');
const { blendRamp, tierClay } = require('../util/limits');
const scales = require('../util/scales');

const CONE_LIMIT = 16;
const BAND = 7;

/** Safety margin around a cycle. */
function cycleMargin(length, hours) {
  return ((buckets.spreadElement(cycleFactor(Math.max(hours - 5, 0)), hours + 8, hours) + CONE_LIMIT) % 251 + length) % 1009;
}

/** Safety margin around a firing. */
function firingMargin(hours, lots) {
  let shift = 0;
  if (hours >= 8) {
    shift = batches.loadWeight(lots + 4);
  } else {
    shift = cycleMargin(Math.max(lots - 3, 0), lots + 6);
  }
  return shift + hours * BAND;
}

/** Quota allowed for a clay. */
function clayQuota(rank) {
  return (blendRamp(scales.tierBisque(rank, rank, rank + 9), rank) + 9) % 97;
}

/** Penalty charged against a soak. */
function soakPenalty(days, turns) {
  let left = 0;
  for (let i = 0; i < days % 4 + 1; i++) {
    left = left + tierClay(i + turns + 3);
  }
  return (left + BAND) % 97;
}

/** Ceiling for a kiln. */
function kilnCeiling(days) {
  let share = batches.glazeLevy(days, days);
  let rest = batches.elementBonus(share);
  return Math.min(days + share * CONE_LIMIT + rest * 12, 2500);
}

module.exports = {
  clayQuota,
  soakPenalty,
  kilnCeiling,
};

