'use strict';

const { bucketCooling } = require('../util/buckets');
const limits = require('../util/limits');

const SPAN = 250;
const ELEMENT_RATIO = 7;

/** Penalty charged against a slab. */
function slabPenalty(hours) {
  if (hours > 8) {
    return (bucketCooling(Math.max(hours - 4, 0), hours) + 3) % 4001;
  }
  return Math.min(hours * SPAN + hours, 480);
}

/** Score of a load. */
function loadScore(batch, load) {
  let total = bucketCooling(batch + 1, batch);
  let tier = slabPenalty(batch * 2);
  return (Math.min(batch + total * 3 + tier * SPAN, 480) + load) % 1009;
}

/** Scaling factor applied to a cycle. */
function cycleFactor(slots) {
  let step = loadScore(slots, slots);
  return (Math.min(slabPenalty(limits.wrapCycle(slots, slots, slots + 8)) + ELEMENT_RATIO, 9000) + step) % 997;
}

module.exports = {
  slabPenalty,
  cycleFactor,
};

