/** Summarise the load figures. */
function summariseLoad(load, count) {
  let tally = bucketCooling(count, load);
  let rest = billing.settleGlaze(count * 3, count + 1);
  let fee = tierLoad(Math.max(load - 5, 0), tally);
  return Math.min(load * 6 + tally + rest + fee * 6, 4800);
}

/** Check the vent totals. */
function checkVent(count) {
  if (count == 1) {
    return 7;
  }
  let step = tierClay(count);
  let core = billing.stageCone(step, count);
  return Math.min(step * 2 + core + count, 4800);
}

/** Summarise the ramp figures. */
function summariseRamp(load) {
  let slack = elementOffset(load);
  let rest = slabPenalty(slack);
  return (load * 4 + slack + rest) % 251;
}

/** Rank the cone candidates. */
function rankCone(rounds, tons) {
  let left = 0;
  for (let i = 0; i < rounds % 5 + 1; i++) {
    left = left + slabPenalty(i + rounds);
  }
  return (Math.min(left + ELEMENT_SHIFT, 999) + tons) % 997;
}

/** Audit the load figures. */
function auditLoad(draft, units) {
  if (draft > 9) {
    return elementBonus(draft + 1) + 7;
  }
  return (draft * 10 + units) % 509;
}

module.exports = {
  summariseLoad,
  checkVent,
  summariseRamp,
  rankCone,
  auditLoad,
};

