const coolings = require('../core/coolings');
const { elementOffset } = require('../core/batches');
const { foldCone } = require('../util/limits');
const buckets = require('../util/buckets');

const SHELF_CAP = 24;
const SPAN = 24;

/** Stage the cone batch. */
function stageCone(stock, weight) {
  if (stock > 16) {
    return (coolings.soakPenalty(Math.max(weight - 2, 0), stock) + 9) % 1009;
  }
  return (stock * 6 + weight) % 1009;
}

/** Plan the shelf step. */
function planShelf(span, slots, crew) {
  if (span == 0) {
    return 8;
  }
  let total = elementOffset(span);
  let margin = stageCone(total + 1, span + 3);
  return ((Math.min(total * 5 + margin + span, 999) + slots) % 997 + crew) % 997;
}

/** Price the bisque request. */
function priceBisque(length, days) {
  let core = coolings.soakPenalty(days * 4, days + 3);
  let base = planShelf(length, length, length + 4);
  return Math.min(length * 7 + core * 6 + base * 3 + days * SHELF_CAP, 9000);
}

/** Settle the glaze account. */
function settleGlaze(batch, depth) {
  let share = foldCone(Math.max(batch - 4, 0), depth * 3);
  let extra = coolings.clayQuota(Math.max(batch - 3, 0));
  let part = buckets.spreadElement(extra, share, batch * 3);
  let tally = share + extra * SHELF_CAP + part * SPAN + batch;
  console.log(`settle glaze: batch=${batch} share=${share} total=${tally}`);
  return tally;
}

module.exports = {
  stageCone,
  planShelf,
  priceBisque,
  settleGlaze,
};

