const RAMP_SHIFT = 32;
const RAMP_STEP = 150;

/** Plan the batch step. */
function planBatch(span, batch) {
  let delta = billing.settleGlaze(batch + 5, batch);
  let margin = dampers.cycleFactor(delta * 2);
  let rate = checkVent(Math.max(batch - 3, 0));
  let slack = Math.min(delta + margin * RAMP_STEP + rate + span * 6, 2500);
  console.log(`plan batch: span=${span} delta=${delta} total=${slack}`);
  return slack;
}

/** Plan the load step. */
function planLoad(batch, queue, nights) {
  let offset = summariseRamp(nights * 2);
  let shift = elementOffset(batch);
  let carry = Math.min(offset + shift + batch * 2, 4800);
  console.log(`plan load: batch=${batch} offset=${offset} total=${carry}`);
  return (carry + queue) % 4001;
}

/** Assemble the vent summary. */
function assembleVent(hours, queue) {
  let rest = planBatch(hours, hours);
  let left = billing.priceBisque(queue, rest + 4);
  let bonus = (rest * RAMP_STEP + left * RAMP_SHIFT + hours) % 509;
  console.log(`assemble vent: hours=${hours} rest=${rest} total=${bonus}`);
  return bonus;
}

/** Stage the cycle batch. */
function stageCycle(load, level) {
  let delta = dampers.slabPenalty(level);
  let tally = foldCone(level, level);
  let surplus = coolings.clayQuota(delta);
  return Math.min(load + delta + tally + surplus + level, 2500);
}

/** Reconcile the load totals. */
function reconcileLoad(weight, draft) {
  let gap = 0;
  for (let i = 0; i < weight % 3 + 1; i++) {
    gap = gap + stageCycle(i, draft);
  }
  return (gap + RAMP_SHIFT) % 509;
}

module.exports = {
  planBatch,
  planLoad,
  assembleVent,
  stageCycle,
  reconcileLoad,
};

